<script lang="ts">
 import {onMount,onDestroy,untrack} from 'svelte';import {anyApi} from 'convex/server';
 import {auth} from '#lib/auth.svelte.ts';import {feed} from '#lib/feed.svelte.ts';
 import {evidenceShortlist} from '#lib/evidence-shortlist.js';import {pct,odds} from '#lib/format.ts';import {SPORTS,SPORT_ORDER} from '#lib/sports.ts';
 let allowed=$state(false),checked=$state(false),loading=$state(false),error=$state(''),report=$state<any>(null),checkedAt=$state(0),now=$state(Date.now());
 let minModel=$state(65),minSamples=$state(20),minStrike=$state(60),minFloor=$state(50),sameLeague=$state(false),sport=$state('all'),kind=$state('all'),search=$state(''),hours=$state(168),shown=$state<Record<string,number>>({});
 let etag='',controller:AbortController|undefined,disposed=false;
 const date=(v:number)=>new Date(v).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'});
 $effect(()=>{const client=auth.client;allowed=false;checked=!client;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r?.isSuperAdmin===true;checked=true;},()=>{error='Administrator access could not be verified.';checked=true;});});
 $effect(()=>{const updated=feed.data?.generatedAt;if(allowed){updated;untrack(()=>void load());}else{controller?.abort();report=null;etag='';}});
 onMount(()=>{const timer=setInterval(()=>now=Date.now(),30000);return()=>clearInterval(timer);});onDestroy(()=>{disposed=true;controller?.abort();});
 async function load(){if(!allowed||loading)return;loading=true;error='';controller=new AbortController();try{
  const response=await fetch('/api/admin/evidence',{headers:etag?{'If-None-Match':etag}:{},cache:'no-store',signal:controller.signal});
  if(response.status===304&&report){checkedAt=Number(response.headers.get('X-Evidence-Checked-At'))||checkedAt;return;}
  if(!response.ok)throw Error(`Evidence catalog could not load (HTTP ${response.status}). Retained results are not replaced with estimates.`);
  let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
  if(bytes.length>64*1024*1024)throw Error('Evidence catalog exceeds the display budget.');const data=JSON.parse(new TextDecoder().decode(bytes));if(data.schema!==1||!Array.isArray(data.upcoming)||!data.groups)throw Error('Evidence catalog format is not supported.');
  if(disposed||!allowed)return;report=data;etag=response.headers.get('ETag')??'';checkedAt=Number(response.headers.get('X-Evidence-Checked-At'))||data.generatedAt;now=Date.now();
 }catch(reason){if(!disposed&&(reason as Error).name!=='AbortError')error=(reason as Error).message;}finally{loading=false;}}
 const valid=$derived([minModel,minSamples,minStrike,minFloor,hours].every(Number.isFinite)&&minModel>=0&&minModel<=100&&minSamples>=1&&minSamples<=100000&&Number.isInteger(minSamples)&&minStrike>=0&&minStrike<=100&&minFloor>=0&&minFloor<=100&&hours>=1);
 const stale=$derived(!checkedAt||now-checkedAt>48*3600000||checkedAt>now+60000);
 const games=$derived(new Map((feed.data?.games??[]).map(g=>[g.id,g])));
 const result=$derived(valid&&report&&!stale?evidenceShortlist(report,{minModel:minModel/100,minSamples,minStrike:minStrike/100,minFloor:minFloor/100,sameLeague,sport,kind,search,hours},now,games):{rows:[],rejected:{}});
 const groups=$derived.by(()=>{const map=new Map<string,any[]>();for(const row of result.rows){if(!map.has(row.group))map.set(row.group,[]);map.get(row.group)!.push(row);}return [...map.entries()];});
 const fixtures=$derived(new Set(result.rows.map((r:any)=>r.fixtureId)).size);
 function reset(){minModel=65;minSamples=20;minStrike=60;minFloor=50;sameLeague=false;sport='all';kind='all';search='';hours=168;shown={};}
 async function proof(fixtureId:string){if(!auth.client)return;try{const meta=await auth.client.query(anyApi.performance.archive,{fixtureId});if(!meta?.url)throw Error('The original archive is not available.');const response=await fetch(meta.url);if(!response.ok)throw Error('The original archive could not load.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`${fixtureId}-published-evidence.gz`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(reason){error=(reason as Error).message;}}
</script>
<svelte:head><title>Evidence shortlist — PuntersEdge administration</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<svelte:window onfocus={()=>{now=Date.now();if(allowed&&now-checkedAt>900000)void load();}} />
<section class="min-w-0 space-y-5">
 <header class="surface relative overflow-hidden p-5 sm:p-7"><div class="pointer-events-none absolute -right-12 -top-12 h-44 w-44 rounded-full bg-model/10 blur-3xl" aria-hidden="true"></div><p class="text-xs font-semibold uppercase tracking-[.18em] text-model">🌡️ Production-ledger intelligence</p><div class="mt-3 flex flex-wrap items-start justify-between gap-4"><div class="min-w-0"><h1 class="text-3xl font-bold sm:text-4xl">Evidence shortlist</h1><p class="mt-3 max-w-3xl text-sm leading-relaxed text-haze">Upcoming published picks with comparable historical outcomes. Ranked by the conservative historical win-rate floor, then strike rate and Model %. Each exact line stays separate.</p></div><a class="btn-secondary" href="/admin/evidence/history">📜 Evidence history</a><button class="btn-secondary" disabled={!allowed||loading} onclick={load}>{loading?'Refreshing…':'Refresh evidence'}</button></div>{#if checkedAt}<p class="mt-4 text-xs text-haze">Pipeline checked {date(checkedAt)} WAT · Original published Model %, independent of personal model settings.</p>{/if}</header>
 {#if error}<div class="surface border-loss/50 p-4" role="alert"><strong class="text-loss">Evidence could not refresh</strong><p class="mt-2 break-words text-sm">{error}</p><button class="btn-secondary mt-3" disabled={loading} onclick={load}>Retry</button></div>{/if}
 {#if !checked}<div class="workspace-state" role="status"><h2>Verifying administrator access</h2></div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><p>This shortlist and its historical evidence are private.</p><a class="btn-primary mt-4" href="/login?next=%2Fadmin%2Fevidence">Sign in</a></div>{:else}
 <section class="surface p-4 sm:p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Selection rules</h2><button class="btn-ghost text-sm" onclick={reset}>Reset rules</button></div><div class="mt-4 grid min-w-0 gap-3 sm:grid-cols-2 xl:grid-cols-4">
 <label class="grid min-w-0 gap-1 text-xs text-haze">Sport<select class="rule-input" bind:value={sport}><option value="all">All supported sports</option>{#each SPORT_ORDER as s}<option value={s}>{SPORTS[s].label}</option>{/each}</select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Market family<select class="rule-input" bind:value={kind}><option value="all">All market families</option><option value="winner">Home / away / draw</option><option value="double-chance">Double chance · all</option><option value="dc1x">Home or draw · 1X</option><option value="dcx2">Away or draw · X2</option><option value="dc12">Home or away · 12</option><option value="team-15">Team over 1.5 goals · football</option><option value="team-05">Team over 0.5 goals · football</option><option value="bttsYes">Both teams to score · Yes · football</option><option value="bttsNo">Both teams to score · No · football</option><option value="first-half-u15">First half Under 1.5 goals · football</option><option value="first-half-u25">First half Under 2.5 goals · football</option><option value="basketball-winner">Basketball / NBA · match winner</option><option value="basketball-spread">Basketball / NBA · spread</option><option value="basketball-total">Basketball / NBA · match total Over / Under</option><option value="basketball-team-over">Basketball / NBA · team total Over</option><option value="basketball-team-under">Basketball / NBA · team total Under</option><option value="basketball-team">Basketball team points · Over / Under</option><option value="match-over">Match totals · Over</option><option value="match-under">Match totals · Under</option><option value="two-consecutive">Team to score two consecutive goals</option><option value="corners">Football corners · Over / Under</option><option value="first-score">First team to score · coverage check</option><option value="match-total">Match Over / Under</option><option value="team-home">Home team Over / Under</option><option value="team-away">Away team Over / Under</option><option value="handicap">Handicap / spread</option><option value="other">Other supported markets</option></select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum Model %<input class="rule-input" type="number" min="0" max="100" bind:value={minModel} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum comparable fixtures<input class="rule-input" type="number" min="1" max="100000" step="1" bind:value={minSamples} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum historical strike %<input class="rule-input" type="number" min="0" max="100" bind:value={minStrike} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Minimum 95% win-rate floor %<input class="rule-input" type="number" min="0" max="100" bind:value={minFloor} /></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Kickoff window<select class="rule-input" bind:value={hours}><option value={24}>Next 24 hours</option><option value={48}>Next 48 hours</option><option value={72}>Next 72 hours</option><option value={168}>Next 7 days</option></select></label>
 <label class="grid min-w-0 gap-1 text-xs text-haze">Fixture / competition / country<input class="rule-input" type="search" bind:value={search} placeholder="Search fixtures or leagues" /></label>
 </div><label class="mt-4 flex min-h-11 items-center gap-3 text-sm"><input type="checkbox" bind:checked={sameLeague} /> Use the same league only</label><p class="mt-2 text-xs leading-relaxed text-haze">Comparable means the same sport, exact outcome and line, period, engine/model version, input-source class and 10-point Model % band. Without the league rule, the pool spans leagues in that sport. This is a defined similarity screen, not a claim that every match circumstance is identical.</p>{#if !valid}<p class="mt-3 text-sm text-loss" role="alert">Enter valid percentages and a positive whole-number sample requirement.</p>{/if}</section>
 {#if loading&&!report}<div class="workspace-state" role="status"><h2>Loading retained evidence</h2><p>Preparing the protected production-ledger catalog.</p></div>{:else if report}
 <div class="grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [['Qualified options',result.rows.length],['Distinct fixtures',fixtures],['Market groups',groups.length],['Historical fixtures',report.historicalFixtures]] as [label,value]}<div class="surface min-w-0 p-4"><p class="text-xs text-haze">{label}</p><p class="mt-2 text-2xl font-bold">{value}</p></div>{/each}</div>
 {#if stale}<div class="workspace-state"><h2>Evidence refresh required</h2><p>The catalog has not been checked within 48 hours. Shortlist publication is paused until fresh metadata is available.</p></div>{/if}
 {#if report.coverage?.missingArchives}<p class="surface p-4 text-sm text-book">{report.coverage.missingArchives} retained archives were unavailable. Counts below describe only the evidence actually read.</p>{/if}
 {#if !result.rows.length&&!stale}<div class="workspace-state"><h2>No upcoming options meet every rule</h2>{#if kind==='corners'}<p class="mt-3 text-sm text-book">Corner collection and chronological training are enabled. Recommendations require sufficient pre-match team histories and a validated model for this league. Missing corners are never treated as zero; extra-time statistics are excluded.</p>{/if}{#if kind==='two-consecutive'}<p class="mt-3 text-sm text-book">Home and away are separate selections. Two consecutive goals means the same team scores twice with no opponent goal between, at any point in regulation time including stoppage time. Extra time and shootouts are excluded. Only forecasts passing chronological league validation can publish. The current rules have no matching validated forecasts and verified goal sequences; team Over 1.5 results cannot substitute for this evidence. No picks or favourable ratings are invented.</p>{/if}{#if kind==='first-score'}<p class="mt-3 text-sm text-book">First-team-to-score is not enabled in this evidence screen: the ledger needs published first-scorer predictions and verified goal-event outcomes. Final scores cannot identify who scored first. No first-scorer history or confidence is fabricated.</p>{/if}<p>Nothing is invented or awarded a green meter to fill the table. There are {report.upcoming.length} published upcoming fixtures in the catalog.</p><p class="mt-3 text-sm">Excluded options: {Object.entries(result.rejected).map(([key,value])=>`${key.replace(/([A-Z])/g,' $1').toLowerCase()}: ${value}`).join(' · ')}</p><p class="mt-3 text-sm">A new model version, exact line or probability band may need more settled fixtures. Adjust the visible thresholds to inspect a broader evidence pool.</p></div>{/if}
 {#if report.research}<details class="surface p-4"><summary class="min-h-11 cursor-pointer py-3 font-semibold">Goal sequence & corner validation · {report.research.eventSequences} verified sequences · {report.research.cornerRecords} corner records</summary><p class="mt-3 text-sm text-haze">Spare-quota collection: at most 6 requests per UTC day, 2 per tick, within the shared football budget. Separate league/home/away models require 200 training fixtures and 100 later validation fixtures across 30 days, calibration error ≤8% and Brier improvement over the earlier base rate. Passing this test does not establish profit.</p><div class="mt-3 space-y-3">{#each report.research.models??[] as m}<div class="rounded-xl border border-line p-3 text-sm"><strong>{m.league} · {m.target}</strong><p>{m.approved?'Validation passed':'Shadow mode'} · Training {m.trainN} · Later validation {m.validation.n}</p><p class="text-xs text-haze">Brier {m.validation.brier?.toFixed(3)??'unavailable'} · Calibration error {m.validation.ece===null?'unavailable':pct(m.validation.ece,1)}</p>{#if m.reasons.length}<p class="mt-2 text-xs text-book">{m.reasons.join(' · ')}</p>{/if}</div>{/each}</div></details>{/if}
 <div class="space-y-5">{#each groups as [group,rows] (group)}<details class="market-group surface min-w-0 overflow-hidden" data-sport={rows[0].sport}><summary class="market-summary flex min-h-14 cursor-pointer flex-wrap items-center justify-between gap-3 p-4 sm:p-5"><div class="min-w-0"><h2 class="break-words text-lg font-bold capitalize">{group}</h2><p class="mt-1 text-xs text-haze">{rows.length} qualifying option{rows.length===1?'':'s'} · {new Set(rows.map(r=>r.fixtureId)).size} fixtures · strongest evidence first</p></div><span class="rounded-full bg-model/10 px-3 py-1 text-xs font-semibold text-model">{pct(rows[0].cohort.interval.low,1)} best floor</span><span class="market-chevron text-haze" aria-hidden="true">⌄</span></summary><p class="px-4 pb-2 text-xs text-haze sm:hidden">Swipe the table to view every metric →</p>
 <div class="max-w-full overflow-x-auto overscroll-x-contain"><table class="evidence-table"><caption class="sr-only">Ranked {group} selections and comparable historical outcomes</caption><thead><tr><th>Rank</th><th>Fixture & competition</th><th>Published selection</th><th>Model %</th><th>Recurrence & proof</th><th>Confidence meter</th><th>Recorded price</th></tr></thead><tbody>{#each rows.slice(0,shown[group]??50) as r (r.id)}<tr><td class="font-mono text-sm text-haze">#{r.rank}</td><td><a class="fixture-name block font-semibold hover:underline" href="/match?id={encodeURIComponent(r.fixtureId)}">{r.matchTitle}</a><p class="mt-2 text-xs text-haze">{r.league}{#if r.tournament&&r.tournament!==r.league} · {r.tournament}{/if}{#if r.country}<br />{r.country}{/if}</p><p class="mt-2 text-xs text-haze">{date(r.kickoff)} WAT</p></td><td><strong class={r.side==='home'||r.kind==='team-home'?'side-home':r.side==='away'||r.kind==='team-away'?'side-away':'text-chalk'}>{r.selection}</strong><p class="mt-2 text-xs text-haze">{r.scope.replaceAll('_',' ')} · Model band {r.probabilityBand*10}–{(r.probabilityBand+1)*10}%</p><p class="mt-1 break-all text-[11px] text-haze">{r.artifact}</p></td><td class="text-lg font-bold text-model">{pct(r.modelProb,1)}</td><td><strong class="text-lg">{pct(r.cohort.strikeRate,1)}</strong><p class="mt-1 text-xs text-haze">{r.cohort.won} wins / {r.cohort.binaryN} binary results</p><p class="mt-1 text-xs text-haze">{r.cohort.lost} lost · {r.cohort.push} returned · {r.cohort.partial} partial</p><p class="mt-1 text-xs text-haze">Quoted history ROI: {r.cohort.quotedRoi===null?'Unavailable':(r.cohort.quotedRoi*100).toFixed(1)+'%'} · {r.cohort.quotedN} quotes</p><details class="mt-2 text-xs"><summary class="min-h-11 cursor-pointer py-3 font-semibold text-pop">Recorded examples & rules</summary><div class="max-w-80 space-y-3 rounded-xl border border-line bg-ink p-3"><p>Pool: {sameLeague?r.league:'same sport across leagues'} · {r.source}. One observation per fixture and exact outcome. Returned and partial stakes are excluded from binary strike rate.</p>{#each r.cohort.examples as example}<div class="border-t border-line pt-2"><strong>{example.matchTitle}</strong><p>{example.league}{example.country?' · '+example.country:''}</p><p>{example.selection} · Model {pct(example.modelProb,1)} · {example.result}</p><p>{date(example.kickoff)} · Final {example.score.home}–{example.score.away}{#if example.score.regHome!==undefined&&example.score.regAway!==undefined&&(example.score.regHome!==example.score.home||example.score.regAway!==example.score.away)} (regulation {example.score.regHome}–{example.score.regAway}){/if}</p><button class="min-h-11 font-semibold text-model underline" onclick={()=>proof(example.fixtureId)}>Download original publication</button></div>{/each}<p>The latest five retained examples are shown; the count covers the full matching cohort.</p></div></details></td><td><strong>{pct(r.cohort.interval.low,1)}</strong><div class="mt-2 h-2.5 w-36 overflow-hidden rounded-full bg-line" role="meter" aria-label="95% historical win-rate lower bound" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Number((r.cohort.interval.low*100).toFixed(1))}><div class="h-full rounded-full transition-[width] duration-300" style:width={`${r.cohort.interval.low*100}%`} style:background={r.cohort.interval.low>=.65?'#22c55e':r.cohort.interval.low>=.5?'#f59e0b':'#ef4444'}></div></div><p class="mt-2 text-xs font-semibold">{r.cohort.interval.low>=.65?'Strong recurrence':r.cohort.interval.low>=.5?'Moderate recurrence':'Weak recurrence'}</p><p class="mt-2 text-xs text-haze">95% Wilson interval<br />{pct(r.cohort.interval.low,1)}–{pct(r.cohort.interval.high,1)}</p><p class="mt-1 text-[11px] text-haze">Historical floor, not fixture win probability.</p></td><td><strong class="text-book">{r.odds>1?odds(r.odds):'Unpriced'}</strong><p class="mt-2 text-xs text-haze">{r.odds>1?'Published snapshot':'No bookmaker quote'}<br />{date(r.publishedAt)}</p></td></tr>{/each}</tbody></table></div>
 {#if rows.length>(shown[group]??50)}<div class="border-t border-line p-4"><button class="btn-secondary" onclick={()=>shown={...shown,[group]:(shown[group]??50)+50}}>Show 50 more · {rows.length-(shown[group]??50)} remaining</button></div>{/if}
 </details>{/each}</div>
 <details class="surface p-4 text-sm"><summary class="min-h-11 cursor-pointer py-3 font-semibold">How the evidence meter works</summary><div class="mt-3 space-y-3 leading-relaxed text-haze"><p>The meter is the lower end of a 95% Wilson interval for the historical win rate. It rises with a stronger observed rate and supporting sample size, and can fall when losses accumulate. Model % remains a separate pre-match estimate.</p><p>Screening many markets can select patterns that do not persist. These descriptive cohorts have not established a profitable out-of-sample strategy. Fixtures can remain related through teams, leagues and time; the interval assumes comparable independent trials.</p><p>Only outcomes with the same exact line and direction are pooled. An Over 2.5 result never supplies evidence for Over 1.5. Different fitted versions are not pooled. Quarter-line settlements remain in the production ledger but are excluded from this binary heat-meter screen. Green means a historical floor of at least65%, amber50–65%, and red below50%. Unpriced outcomes can contribute recurrence evidence; they cannot establish a quoted-price return.</p><p>Started fixtures are removed by the local clock (checked every 30 seconds), and completed/live status changes remove them when the feed updates. New published fixtures enter after the scheduled pipeline refresh, normally approximately every 30 minutes. All qualifying options are counted; groups initially show 50 rows for rendering performance.</p><a class="font-semibold text-model underline" href="https://www.itl.nist.gov/div898/handbook/prc/section2/prc241.htm" target="_blank" rel="noreferrer">NIST methodology for proportion confidence intervals ↗</a></div></details>
 {/if}{/if}
</section>
<style>
 .market-group[data-sport="football"]>.market-summary{background:color-mix(in srgb,#86efac 16%,var(--color-raised));border-left:4px solid #86efac;}.market-group[data-sport="hockey"]>.market-summary{background:color-mix(in srgb,#7dd3fc 16%,var(--color-raised));border-left:4px solid #7dd3fc;}.market-group[data-sport="basketball"]>.market-summary,.market-group[data-sport="nba"]>.market-summary{background:color-mix(in srgb,#fcd34d 16%,var(--color-raised));border-left:4px solid #fcd34d;}.market-group[data-sport="baseball"]>.market-summary{background:color-mix(in srgb,#c4b5fd 16%,var(--color-raised));border-left:4px solid #c4b5fd;}
 .market-summary{list-style:none;}.market-summary::-webkit-details-marker{display:none;}.market-summary:focus-visible{outline:2px solid var(--color-model);outline-offset:-3px;}.market-summary>div{flex:1 1 220px;}.market-chevron{font-size:1.5rem;line-height:1;}.market-group[open]>.market-summary .market-chevron{transform:rotate(180deg);}
 .rule-input{min-height:44px;width:100%;min-width:0;border:1px solid var(--color-line);border-radius:.75rem;background:var(--color-ink);color:var(--color-chalk);padding:.65rem .75rem;font-size:.875rem;}
 .evidence-table{width:100%;min-width:1160px;font-size:.875rem;}.evidence-table th,.evidence-table td{padding:1rem;vertical-align:top;text-align:left;}.evidence-table th{font-size:.7rem;text-transform:uppercase;letter-spacing:.06em;color:var(--color-haze);background:var(--color-raised);}.evidence-table td{border-top:1px solid var(--color-line);}.evidence-table td:nth-child(2){min-width:230px;max-width:290px;}.evidence-table td:nth-child(3){min-width:185px;max-width:240px;}.evidence-table tbody tr{transition:background-color .18s;}.evidence-table tbody tr:hover{background:color-mix(in srgb,var(--color-model) 5%,transparent);}
 @media(prefers-reduced-motion:reduce){.evidence-table tbody tr{transition:none;}}
</style>
